# Verify
sys.path.insert(0, '.')
if 'tools.expansion.ip_aztec_ext' in sys.modules:
    del sys.modules['tools.expansion.ip_aztec_ext']
from tools.expansion.ip_aztec_ext import HEROES
short = []
for h in HEROES:
    for sk in h['skills']:
        if len(sk[1]) < 20:
            short.append((h['name'], sk[0], len(sk[1])))
if short:
    print(f"Still {len(short)} short:")
    for s in short:
        print(f"  {s}")
else:
    print("All descriptions >= 20 chars: OK!")
print(f"Total heroes: {len(HEROES)}")
